{
  "flags": [
    {
      "claim": 2,
      "label": "unsupported",
      "evidence": ["eda:Base_Salary", "seg:Department/Base_Salary"],
      "evidence_says": "eda:Base_Salary shows salary statistics (mean 84,622.10, median 82,700.00, range 34,400–170,800); seg:Department/Base_Salary shows mean salary by department. Neither evidence item contains information about new joiners, their tenure, or their separation patterns.",
      "reason": "The claim states that hiring 70 people pushed attrition up to 14.3% because new joiners left first. The cited evidence contains only salary data by department and overall salary statistics; it does not show hire dates, tenure, or separation patterns by cohort or time-in-role. No evidence supports this causal claim."
    }
  ],
  "gaps": [
    {
      "text": "The analysis does not show attrition or separation patterns by department, which is needed to understand whether the overall 6.7-point improvement is evenly distributed or concentrated in specific areas.",
      "columns": ["Department", "Termination_Date", "Snapshot_Date"]
    },
    {
      "text": "No breakdown of hires or separations by cohort (hire date or tenure) is provided, so it is unclear whether new joiners have higher or lower attrition than tenured staff, or what role they played in the overall attrition change.",
      "columns": ["Hire_Date", "Termination_Date", "Snapshot_Date"]
    },
    {
      "text": "The analysis does not segment attrition or headcount trends by worker type, location, or other dimensions that might explain the 6.7-point improvement between the two 12-month periods.",
      "columns": ["Worker_Type", "Location", "Snapshot_Date", "Termination_Date"]
    }
  ],
  "methodology_concerns": [
    {
      "text": "Salary data is shown unadjusted for full-time equivalents (FTE), so groups with more part-timers will show lower average pay than on an FTE-adjusted basis. The evidence notes this applies to gender groups; it may also affect department comparisons if departments differ in part-time headcount.",
      "columns": ["Base_Salary", "FTE", "Department"]
    }
  ],
  "next_investigations": [
    {
      "text": "Segment attrition rate and separations by department over the 12-month periods to October 2025 and October 2026 to identify which departments drove the 6.7-point improvement.",
      "columns": ["Department", "Snapshot_Date", "Termination_Date"]
    },
    {
      "text": "Compare separation rates by hire cohort (employees hired before vs. after key dates) to assess whether new joiners have higher attrition than tenured staff.",
      "columns": ["Hire_Date", "Termination_Date", "Snapshot_Date"]
    },
    {
      "text": "Analyze headcount and attrition trends by worker type and location to determine whether the improvement is driven by changes in workforce composition or retention within existing groups.",
      "columns": ["Worker_Type", "Location", "Snapshot_Date", "Termination_Date"]
    }
  ]
}
```

